    if (name === 'health') return send(res, 200, { ok: true });
    if (name === 'auth') return send(res, 200, { name: body.name || 'Guest', email: body.email || '', token: id() + id() });
    const list = db[name]; if (!list) return send(res, 404, { error: 'Unknown resource ' + name });
    const i = key ? list.findIndex((x) => x.id === key) : -1;
    if (req.method === 'GET' && !key) return send(res, 200, list);
    if (key && i < 0) return send(res, 404, { error: 'Not found' });
    if (req.method === 'GET') return send(res, 200, list[i]);
